+fn arc(c: Point2, r: f64, a0: f64, a1: f64, n: usize) -> Vec<Point2> {
+    (0..=n).map(|i| a0 + (a1 - a0) * i as f64 / n as f64).map(|a| Point2::new(c.x + r * a.cos(), c.y + r * a.sin())).collect()
