+    match OrderStage.order(r.set.clone(), &r.region, &OrderChoice::default(), None) {
+        Ok(v) => v.out().unwrap().clone(),
+        Err(_) => {
+            let start = r.set.curves()[0].pts()[0].at();
+            OrderedSet::new(&r.set, r.set.curves().to_vec(), start, StartSide::Inside).unwrap()
+        }
+    }
+}
